// Handle all items in runOnceForAllItems mode
const results = [];
for (const item of $input.all()) {
  const raw = item.json.dob || "";
  let year, month, day;
  if (raw.match(/^\d{4}-\d{2}-\d{2}$/)) {
    // "YYYY-MM-DD"
    [year, month, day] = raw.split("-").map(Number);
  } else if (raw.match(/^\d{1,2}\/\d{1,2}\/\d{4}$/)) {
    // "MM/DD/YYYY"
    [month, day, year] = raw.split("/").map(Number);
  } else {
    results.push({
      json: {
        ...item.json,
        error: "DOB missing/invalid"
      }
    });
    continue;
  }
  const now = new Date();
  let thisYear = now.getFullYear();
  let next = new Date(thisYear, month-1, day, 8, 0, 0, 0);
  if (next < now) next = new Date(thisYear+1, month-1, day, 8, 0, 0, 0);
  const birthday8am = next.toISOString();
  const twoWeeksBefore = new Date(next.getTime() - 14*24*60*60*1000).toISOString();

  results.push({
    json: {
      ...item.json,
      birthday8am,
      twoWeeksBefore,
    }
  });
}
return results;

