// Get recipient data from "Wait 2 weeks before" node
const waitData = (() => { 
  try { 
    return $('Wait 2 weeks before').first()?.json || {}; 
  } catch { 
    return {}; 
  } 
})();

// Get all gift items that were picked
const gifts = items.map(i => i.json);

// Budget label
const budget = (gifts[0]?.budget_min != null && gifts[0]?.budget_max != null)
  ? `$${gifts[0].budget_min} - $${gifts[0].budget_max}`
  : 'any budget';

// Build HTML email with all gifts
let html = `
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8"/>
<style>
body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; background: #f5f5f5; margin: 0; padding: 20px; }
.container { max-width: 700px; margin: 0 auto; background: #fff; padding: 30px; border-radius: 12px; box-shadow: 0 2px 8px rgba(0,0,0,0.1); }
h2 { color: #2c3e50; border-bottom: 3px solid #3498db; padding-bottom: 10px; margin-bottom: 20px; }
.budget-info { background: #fff3cd; border-left: 4px solid #ffc107; padding: 12px; margin-bottom: 25px; border-radius: 4px; }
.gift-item { border: 1px solid #e0e0e0; padding: 20px; margin-bottom: 20px; border-radius: 8px; background: #fafafa; display: flex; gap: 20px; }
.gift-item img { width: 150px; height: 150px; object-fit: contain; border: 1px solid #ddd; border-radius: 6px; padding: 5px; background: white; }
.gift-details { flex: 1; }
.gift-details h3 { margin: 0 0 10px 0; color: #2980b9; font-size: 18px; }
.category { display: inline-block; background: #e8f4f8; color: #2980b9; padding: 4px 12px; border-radius: 12px; font-size: 12px; margin-bottom: 8px; }
.reason-box { background: #e8f4f8; border-left: 4px solid #3498db; padding: 12px; margin: 12px 0; border-radius: 4px; font-style: italic; line-height: 1.5; }
.price { font-weight: bold; color: #27ae60; font-size: 1.2em; margin: 10px 0; }
.product-link { display: inline-block; padding: 10px 20px; background: #3498db; color: white !important; text-decoration: none; border-radius: 6px; margin-top: 12px; }
.product-link:hover { background: #2980b9; }
.footer { margin-top: 30px; text-align: center; color: #7f8c8d; font-size: 0.9em; padding-top: 20px; border-top: 1px solid #ddd; }
</style>
</head>
<body>
  <div class="container">
    <h2>🎁 Hi ${waitData.recipient_name || 'there'}! Here are ${gifts.length} gift ideas for you!</h2>
    <div class="budget-info"><strong>Budget Range:</strong> ${budget}</div>
`;

gifts.forEach((gift, i) => {
  const linkOk = gift.link && /^https?:\/\//i.test(gift.link);
  const img = gift.imageUrl || 'https://via.placeholder.com/150?text=No+Image';

  html += `
    <div class="gift-item">
      <img src="${img}" alt="${gift.product_name || gift.gift_name}" onerror="this.src='https://via.placeholder.com/150?text=No+Image'">
      <div class="gift-details">
        <span class="category">${gift.gift_category || 'Gift Idea'}</span>
        <h3>${i + 1}. ${gift.gift_name}</h3>
        <p><strong>Product:</strong> ${gift.product_name || gift.gift_name}</p>

        ${gift.gift_description ? `<p style="margin:6px 0 8px 0;">${gift.gift_description}</p>` : ''}

        <div class="reason-box">
          <strong>Why this gift?</strong><br>
          ${gift.gift_reason || 'A thoughtful gift idea.'}
        </div>

        <div class="price">${gift.price || ''}</div>
        <p style="font-size: 0.85em; color: #7f8c8d;">Available at: ${gift.source || 'Online'}</p>
        ${linkOk
          ? `<a class="product-link" href="${gift.link}" target="_blank" rel="noopener noreferrer">View Product →</a>`
          : `<p style="color:#e74c3c;font-style:italic;">Product link unavailable</p>`}
      </div>
    </div>
  `;
});

html += `
    <p style="text-align:center;margin-top:20px;font-size:1.05em;">Have fun choosing! 🎉</p>
    <div class="footer">This email was sent automatically with n8n.</div>
  </div>
</body>
</html>
`;

// ✅ Return with all recipient data included
return [{
  json: {
    emailHtml: html,
    recipient_name: waitData.recipient_name || 'there',
    recipient_email: waitData.recipient_email || '', // ✅ This is the key field
    recipient_whatsapp: waitData.recipient_whatsapp || ''
  }
}];

// Get all input data
const input = $json;

// Extract budget values
const budget_min = Number(input.budget_min) || 0;
const budget_max = Number(input.budget_max) || 0;

// Create budget label
let budget_label = '';
if (budget_max <= 20) {
  budget_label = 'Under $20';
} else if (budget_max <= 50) {
  budget_label = '$20-$50';
} else if (budget_max <= 100) {
  budget_label = '$50-$100';
} else {
  budget_label = 'Over $100';
}

console.log(`Parsed budget: $${budget_min} - $${budget_max}`);

// ✅ Return ALL input data PLUS the parsed budget fields
return [{
  json: {
    ...input,  // ✅ This preserves ALL the recipient data!
    budget_min: budget_min,
    budget_max: budget_max,
    budget_label: budget_label
  }
}];

// Get AI response
const aiResponse = $('Message a model').first().json;

// Try to get recipient data from multiple sources
let recipientData = {
  recipient_name: '',
  recipient_email: '',
  recipient_whatsapp: '',
  dob_iso: '',
  dob_next: '',
  budget_min: 20,
  budget_max: 50,
  budget_label: 'Under $20'
};

// Source 1: Try from "Message a model" input
try {
  const msgInput = $input.first().json || {};
  console.log("Message a model received:", JSON.stringify(msgInput));
  if (msgInput.recipient_email) {
    recipientData = { ...recipientData, ...msgInput };
    console.log("✅ Got recipient data from Message input");
  }
} catch (e) {
  console.log("Could not access Message input:", e.message);
}

// Source 2: If still empty, try "Wait 2 weeks before"
if (!recipientData.recipient_email) {
  try {
    const waitOutput = $('Wait 2 weeks before').first().json || {};
    if (waitOutput.recipient_email) {
      recipientData = { ...recipientData, ...waitOutput };
      console.log("✅ Got recipient data from Wait node");
    }
  } catch (e) {
    console.log("Could not access Wait node:", e.message);
  }
}

// Source 3: If still empty, try "Parse budget"
if (!recipientData.recipient_email) {
  try {
    const budgetOutput = $('Parse budget').first().json || {};
    if (budgetOutput.recipient_email) {
      recipientData = { ...recipientData, ...budgetOutput };
      console.log("✅ Got recipient data from Parse budget");
    }
  } catch (e) {
    console.log("Could not access Parse budget:", e.message);
  }
}

console.log("Final recipient data:", {
  name: recipientData.recipient_name || 'MISSING',
  email: recipientData.recipient_email || 'MISSING',
  budget: `${recipientData.budget_min}-${recipientData.budget_max}`
});

// Extract ideas array from AI response
let ideas = [];
if (aiResponse?.message?.content?.ideas) {
  ideas = aiResponse.message.content.ideas;
} else if (aiResponse?.content?.ideas) {
  ideas = aiResponse.content.ideas;
} else if (typeof aiResponse?.message?.content === 'string') {
  try {
    const parsed = JSON.parse(aiResponse.message.content);
    ideas = parsed.ideas || [];
  } catch (e) {
    console.log("Failed to parse AI response");
  }
}

console.log(`Found ${ideas.length} gift ideas from AI`);

if (!ideas || ideas.length === 0) {
  throw new Error("AI did not return any gift ideas");
}

// Return each idea as a separate item with ALL recipient data
return ideas.map((idea, index) => {
  console.log(`\nIdea ${index + 1}: ${idea.name}`);

  return {
    json: {
      // ✅ ALL recipient data
      recipient_name: recipientData.recipient_name || 'there',
      recipient_email: recipientData.recipient_email || '',
      recipient_whatsapp: recipientData.recipient_whatsapp || '',
      dob_iso: recipientData.dob_iso || '',
      dob_next: recipientData.dob_next || '',
      mode: recipientData.mode || 'easy',
      interests: recipientData.interests || [],

      // Idea data
      idea_index: index + 1,
      category: idea.category || '',
      name: idea.name || '',
      description: idea.description || idea.desc || '',
      reason: idea.reason || 'A thoughtful gift idea',
      query: idea.query || idea.name || '',

      // Budget data
      budget_min: recipientData.budget_min || 20,
      budget_max: recipientData.budget_max || 50,
      budget_label: recipientData.budget_label || `$${recipientData.budget_min || 20} - $${recipientData.budget_max || 50}`
    }
  };
});

// Read the single merged item only (no $items() cross-reads)
const item            = $json;
const results         = item.shopping_results || [];

// Idea fields (kept all the way to email)
const giftName        = item.idea_name || 'Gift Idea';
const giftDescription = item.idea_description || '';
const giftReason      = item.idea_reason || '';
const giftCategory    = item.idea_category || '';

// Budget (robust defaults)
const budget_min = Number.isFinite(+item.budget_min) ? +item.budget_min : 20;
const budget_max = Number.isFinite(+item.budget_max) ? +item.budget_max : 50;

// --- helpers ---
function priceOf(r) {
  if (r && r.extracted_price != null && !isNaN(r.extracted_price)) return Number(r.extracted_price);
  if (r && r.price) {
    const m = String(r.price).replace(/,/g, '').match(/(\d+(\.\d+)?)/);
    return m ? Number(m[1]) : null;
  }
  return null;
}

// Filter candidates by budget
const inBudget = results.filter(r => {
  const p = priceOf(r);
  return p != null && p >= budget_min && p <= budget_max;
});

// Pick product: prefer a budget match; otherwise cheapest with a price
let product = null;
if (inBudget.length) {
  product = inBudget[0];
} else {
  const priced = results.filter(r => priceOf(r) != null);
  if (priced.length) {
    priced.sort((a, b) => priceOf(a) - priceOf(b));
    product = priced[0];
  }
}

// If nothing usable, return a graceful placeholder (keeps the slot in the email)
if (!product) {
  return {
    json: {
      gift_name:        giftName,
      gift_category:    giftCategory,
      gift_reason:      giftReason,
      gift_description: giftDescription,
      product_name:     giftName,
      price:            'Price not available',
      imageUrl:         'https://via.placeholder.com/150?text=No+Result',
      link:             '',
      source:           'Online',
      budget_min,
      budget_max
    }
  };
}

// Build output for a real product
const p          = priceOf(product);
const priceText  = (p != null) ? `$${p.toFixed(2)}` : 'Price not available';
const link       = product.product_link || product.link || product.url || product.serpapi_link || '';
const image      = product.thumbnail || 'https://via.placeholder.com/150';
const chosenName = product.title || giftName;

return {
  json: {
    gift_name:        giftName,
    gift_category:    giftCategory,
    gift_reason:      giftReason,
    gift_description: giftDescription,   // <- will render in the email
    product_name:     chosenName,
    price:            priceText,
    imageUrl:         image,
    link,
    source:           product.source || 'Online',
    budget_min,
    budget_max
  }
};

// Safely fetch the matching idea from "Split ideas into items".
// When this node is executed alone, $items() may throw or return an Error object.
// We swallow that and fall back to any idea_* fields already on $json.

function safeGetIdea() {
  try {
    const prev = $items('Split ideas into items', 0, $itemIndex);
    // If prev is a real item with json, use it
    if (prev && prev.json && typeof prev.json === 'object') return prev.json;
  } catch (e) {
    // ignore; we'll fall back below
  }
  // Fallback: if upstream already carried idea_* fields on $json, convert them back
  const j = $json || {};
  if (j.idea_name || j.idea_description || j.idea_reason || j.idea_category || j.idea_query) {
    return {
      name: j.idea_name,
      description: j.idea_description,
      reason: j.idea_reason,
      category: j.idea_category,
      query: j.idea_query,
      budget_min: j.budget_min,
      budget_max: j.budget_max,
    };
  }
  return {};
}

const idea = safeGetIdea();
const http = $json; // HTTP Request output for this item

return {
  json: {
    // keep all HTTP fields (shopping_results, search_metadata, etc.)
    ...http,

    // stable AI idea fields
    idea_name:        idea.name || '',
    idea_description: idea.description || idea.desc || '',
    idea_reason:      idea.reason || '',
    idea_category:    idea.category || '',
    idea_query:       idea.query || '',

    // budget with sane defaults
    budget_min:       (idea.budget_min ?? 20),
    budget_max:       (idea.budget_max ?? 50),
  }
};

// Get the normalized data from "Wait 2 weeks before" node
// This contains all recipient information
const waitData = (() => { 
  try { 
    return $('Wait 2 weeks before').first()?.json || {}; 
  } catch { 
    return {}; 
  } 
})();

// Current idea from this iteration
const i = $json;

// Combine everything: recipient info + idea details + budget
return {
  json: {
    // ✅ Recipient information (from Wait node)
    recipient_name: waitData.recipient_name || '',
    recipient_email: waitData.recipient_email || '',
    recipient_whatsapp: waitData.recipient_whatsapp || '',
    dob_iso: waitData.dob_iso || '',
    dob_next: waitData.dob_next || '',

    // ✅ Idea details (from current item)
    idea_name: i.name || '',
    idea_description: i.description || i.desc || '',
    idea_reason: i.reason || '',
    idea_category: i.category || '',
    idea_query: i.query || (i.name || ''),

    // ✅ Budget (from current item with fallbacks)
    budget_min: Number.isFinite(+i.budget_min) ? +i.budget_min : waitData.budget_min || 20,
    budget_max: Number.isFinite(+i.budget_max) ? +i.budget_max : waitData.budget_max || 50
  }
};

// Helper accessors
const body = $json.body || $json || {};
const pick = (k, def = '') => (body[k] ?? $json[k] ?? def);

// Turn any incoming value into a clean array:
// - already an array -> filtered
// - comma-separated string -> split
// - single value -> [value]
// - null/undefined -> []
const arr = (k) => {
  let v = body[k] ?? $json[k];
  if (v == null) return [];
  if (Array.isArray(v)) return v.filter(Boolean);
  if (typeof v === 'string') {
    const s = v.trim();
    if (!s) return [];
    if (s.includes(',')) {
      return s.split(',').map(x => x.trim()).filter(Boolean);
    }
    return [s];
  }
  return [];
};

// Mode (easy / medium / detailed(hard))
const mode = (pick('mode', 'easy') || '').toLowerCase();

// Basic identity fields (try multiple keys to be resilient)
const name = pick('full_name') || pick('Full Name');
const email = pick('email') || pick('Email');
const whatsapp = pick('whatsapp') || pick('WhatsApp') || pick('WhatsApp Number') || pick('phone');

// Date of birth (accepts yyyy-mm-dd or mm/dd/yyyy etc.)
const dobRaw = pick('dob') || pick('Date of Birth');
const dob = dobRaw ? new Date(dobRaw) : null;
const dobIso = dob && !isNaN(dob.getTime()) ? dob.toISOString().slice(0, 10) : '';

// Compute next birthday (UTC) in YYYY-MM-DD for calendar creation
function nextBirthdayUTC(d) {
  if (!d || isNaN(d.getTime())) return '';
  const now = new Date();
  const todayUTC = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate()));
  let next = new Date(Date.UTC(todayUTC.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  if (next < todayUTC) next.setUTCFullYear(next.getUTCFullYear() + 1);
  return next.toISOString().slice(0, 10);
}
const dobNext = nextBirthdayUTC(dob);

// Budget
const budgetMin = Number(pick('budget_min', '0')) || 0;
const budgetMax = Number(pick('budget_max', '0')) || 0;

// Interests by mode
const interests =
  mode === 'easy'   ? arr('interests_easy[]') :
  mode === 'medium' ? arr('interests_medium[]') :
                      arr('interests_hard[]');

// Gift types (support either a shared field or per-mode fields)
const giftTypes = [
  ...arr('gift_types[]'),
  ...arr('gift_types_medium[]'),
  ...arr('gift_types_hard[]'),
].filter(Boolean);
const giftTypesUnique = [...new Set(giftTypes)];

// Brands & colors vary by mode (medium vs detailed)
const brands = mode === 'medium' ? arr('brands_medium[]') : arr('brands_hard[]');
const colors = mode === 'medium' ? arr('colors_medium[]') : arr('colors_hard[]');

// “Avoid” notes (only on detailed form typically)
const avoid = pick('avoid') || pick('avoid_hard') || '';

// Build normalized payload (flat fields for easy use downstream)
const out = {
  mode,
  recipient_name: name || '',
  recipient_email: email || '',
  recipient_whatsapp: whatsapp || '',

  dob_raw: dobRaw || '',
  dob_iso: dobIso,          // YYYY-MM-DD of the original DOB
  dob_next: dobNext,        // YYYY-MM-DD for the next birthday (this/next year, UTC)

  budget_min: budgetMin,
  budget_max: budgetMax,

  interests,
  gift_types: giftTypesUnique,
  brands,
  colors,
  avoid,

  // CSV helpers for emails/sheets
  interests_csv: interests.join(', '),
  gift_types_csv: giftTypesUnique.join(', '),
  brands_csv: brands.join(', '),
  colors_csv: colors.join(', '),

  // A compact blob if you need to pass around a single string
  profile_json: JSON.stringify({
    mode,
    name,
    email,
    whatsapp,
    dob: dobIso,
    nextBirthday: dobNext,
    budget: { min: budgetMin, max: budgetMax },
    interests,
    giftTypes: giftTypesUnique,
    brands,
    colors,
    avoid
  })
};

// Emit one item
return [{ json: out }];

// Input: the normalized form payload at $json
// Output: { personaText, recipientName, styleHints }

const f = $json || {};

const recipientName   = $input.first().json.recipient_name || f.name || "there";
const relationship    = f.relationship || f["Relationship (who is this person to you)"] || "";
const age             = f.age || f["Age"] || "";
const pronouns        = f.pronouns || f["Pronouns"] || "";
const likes           = f.likes || f["Likes / Interests"] || "";
const dislikes        = f.dislikes || f["Dislikes"] || "";
const favorites       = f.favorites || f["Favorites (color, teams, animals, etc.)"] || "";
const hobbies         = f.hobbies || f["Hobbies"] || "";
const vibe            = f.vibe || f["Vibe for the card (cute, elegant, funny, minimal, etc.)"] || "joyful, celebratory";
const theme           = f.theme || f["Theme ideas (pandas, space, soccer, etc.)"] || "";
const palette         = f.palette || f["Color palette"] || "";
const messageTone     = f.message_tone || f["Message tone"] || "warm and cheerful";

// Compose a single persona block
const personaText = [
  `Recipient: ${recipientName}`,
  relationship && `Relationship: ${relationship}`,
  age && `Age: ${age}`,
  pronouns && `Pronouns: ${pronouns}`,
  likes && `Likes: ${likes}`,
  dislikes && `Dislikes: ${dislikes}`,
  favorites && `Favorites: ${favorites}`,
  hobbies && `Hobbies: ${hobbies}`,
  theme && `Preferred theme: ${theme}`,
  palette && `Color palette: ${palette}`,
  `Card vibe: ${vibe}`,
  `Message tone: ${messageTone}`
].filter(Boolean).join("\n");

const styleHints = { vibe, theme, palette, messageTone };

return [{ json: { personaText, recipientName, styleHints } }];

// Prepare Prompt for Birthday Image Generation
const personaData = $json;

// Get recipient information
const recipientName = personaData.recipientName || "Friend";
const recipientFirst = personaData.recipientFirst || recipientName.split(" ")[0] || "Friend";

// Calculate age from date of birth
let age = null;
const dobRaw = personaData.dob_raw || personaData.dob || personaData.dateOfBirth;

console.log("Date of birth (dob_raw):", dobRaw);

if (dobRaw) {
  try {
    const dob = new Date(dobRaw);
    const today = new Date();

    age = today.getFullYear() - dob.getFullYear();
    const monthDiff = today.getMonth() - dob.getMonth();

    if (monthDiff < 0 || (monthDiff === 0 && today.getDate() < dob.getDate())) {
      age--;
    }

    console.log(`✅ Calculated age for ${recipientFirst}: ${age} years old`);
  } catch (error) {
    console.log("❌ Error calculating age:", error.message);
  }
}

// Build the image generation prompt with MORE DYNAMIC elements
const prompt = `Create a vibrant, high-energy birthday celebration photograph with dynamic composition.

SCENE COMPOSITION:
- Center: A spectacular multi-tiered birthday cake${age ? ` with lit candles showing number "${age}"` : ' with lit candles'}
- Foreground: Flying confetti mid-air, balloons floating upward
- Background: Soft bokeh lights, party decorations, string lights
- Action: Capture the moment confetti is being thrown, creating motion and energy
- Setting: Warm, cozy party atmosphere with depth of field

